import{_ as n,o as i,c as s,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/tutorials-gym-sprachenfolge-wechsler-1.png",t="/bilder/vorbereitung/tutorials-gym-sprachenfolge-wechsler-2.png",m=JSON.parse('{"title":"Sprachenfolgen bei Seiteneinstieg ins Gymnasium ausgeben","description":"","frontmatter":{"title":"Sprachenfolgen bei Seiteneinstieg ins Gymnasium ausgeben","source_pageid":857,"source_revision":5522},"headers":[],"relativePath":"zeugnisse/vorbereitung/sprachenfolge-bei-seiteneinsteigern-des-gymnasiums-in-zeugnissen-korrekt-ausgeben-tutorial.md","filePath":"zeugnisse/vorbereitung/sprachenfolge-bei-seiteneinsteigern-des-gymnasiums-in-zeugnissen-korrekt-ausgeben-tutorial.md"}'),l={name:"zeugnisse/vorbereitung/sprachenfolge-bei-seiteneinsteigern-des-gymnasiums-in-zeugnissen-korrekt-ausgeben-tutorial.md"};function g(u,e,o,h,c,p){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="sprachenfolgen-bei-seiteneinstieg-ins-gymnasium-ausgeben" tabindex="-1">Sprachenfolgen bei Seiteneinstieg ins Gymnasium ausgeben <a class="header-anchor" href="#sprachenfolgen-bei-seiteneinstieg-ins-gymnasium-ausgeben" aria-label="Permalink to &quot;Sprachenfolgen bei Seiteneinstieg ins Gymnasium ausgeben&quot;">​</a></h1><p>Pflegen Sie bisherigen Schulbesuch und Sprachenfolge bei Schülerinnen und Schülern, die nach Klasse 10 ins Gymnasium wechseln. Die Anleitung erläutert abgeschlossene Fremdsprachen und manuelle Qualifikationseinträge.</p><p>Diese Anleitung behandelt die Druckausgabe der Sprachenfolge beim Wechsel von einer Haupt- oder Realschule nach Klasse 10 an ein Gymnasium. Sie gilt für Schülerinnen und Schüler, die in der Sekundarstufe I eine zweite Fremdsprache belegt und abgeschlossen haben, zum Beispiel von Klasse 8 bis 10.</p><p>Folgendermaßen muss vorgegangen werden:</p><p><a href="/bilder/vorbereitung/tutorials-gym-sprachenfolge-wechsler-1.png"><img src="'+a+'" alt="Anlegen der vorherigen Schule." loading="lazy"></a></p><p><em>Anlegen der vorherigen Schule.</em></p><p>Zuerst ist der <em>Schulbesuch</em> zu kontrollieren.</p><p>Dieser wird unter <em>Schüler Schulbesuch</em> aufgerufen.</p><p>In diesem Fenster ist die alte Schule mit den Daten und dem korrekten Entlassjahrgang einzutragen.</p><p>Übernehmen Sie die Schule mit dem nach rechts gerichteten Pfeil in <strong>Alle bisher besuchten Schulen</strong>.</p><p><a href="/bilder/vorbereitung/tutorials-gym-sprachenfolge-wechsler-2.png"><img src="'+t+'" alt="Eingeben der bisherigen Sprachenfolgen." loading="lazy"></a></p><p><em>Eingeben der bisherigen Sprachenfolgen.</em></p><p>Geben Sie nun die Sprachenfolge ein.</p><p>Die erste Fremdsprache ist Englisch - und, außer, Sie erstellen nun ein Abgangszeugnis, bislang nicht abgeschlossen und wird also nur mit dem Beginn der Belegung eingetragen (üblicherweise Englisch ab der Klasse 5, 1. Halbjahr).</p><p>Die <strong>zweite Fremdsprache</strong> ist das von 6 bis 10 an der anderen Schule fertig belegte und hier an der Schule abgeschlossene Französisch. Diese Sprache wird nun mit den korrekten Abschnittsdaten &quot;<strong>von</strong>&quot; und &quot;<strong>bis&quot;</strong> befüllt.</p><p>Gleichermaßen lassen sich weitere begonnene oder auch abgeschlossene Fremdsprachen eintragen.</p><p>Tragen Sie das Referenzniveau manuell ein. Sofern ein Latinum, Greacum oder Hebraicum erreicht, tragen Sie dies ebenfalls - wie immer manuell - ein.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sprachenfolge_bei_Seiteneinsteigern_des_Gymnasiums_in_Zeugnissen_korrekt_ausgeben_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5522.</p>',19)])])}const b=n(l,[["render",g]]);export{m as __pageData,b as default};
